    long long m, n;
    bool r = false;
    cin >> n >> m;

    long long x = n * m;
    long long k = x;
    int count = 0;

    while (k != 0 && k % 10 == 0) {
        ++count;
        k /= 10;
    }

    if (count > 0 && x % (count * 10LL) == 0 &&
        (x / (count * 10LL)) % 2 != 0)
        r = false;
    else if (x == 2)
        r = false;
    else if (x % 2 == 0)
        r = true;

    cout << (r ? "Malvika" : "Akshat") << '\n';
    return 0;
}

